return {["scripts/actions/spells/white/diaga.lua"]={["Path"]="scripts/actions/spells/white/diaga.lua",["SHA256"]="d32e6385c50d6874a82b88dfc30906f2cc7279b9c7e8055c1237ceb38bde0907",["Text"]="-----------------------------------\n-- Spell: Diaga\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 1\n\n    -- Check for Bio\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = 1 + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = 60, origin = caster, tick = 3, subPower = 10, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/diaga_ii.lua"]={["Path"]="scripts/actions/spells/white/diaga_ii.lua",["SHA256"]="e8d2358ff67282ee41435b7426453e4423935aa8ca255a5d5812f441bb2b1e75",["Text"]="-----------------------------------\n-- Spell: Diaga II\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 3\n\n    -- Check for Bio\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = 2 + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = 120, origin = caster, tick = 3, subPower = 15, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/diaga_iii.lua"]={["Path"]="scripts/actions/spells/white/diaga_iii.lua",["SHA256"]="5d3fa87dc2adb0982ddce67f2f6a3cbb0bb399a2fd3f36beb6e8143a2c5549d9",["Text"]="-----------------------------------\n-- Spell: Diaga III\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 5\n\n    -- Check for Bio\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = 3 + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = 180, origin = caster, tick = 3, subPower = 20, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/diaga_iv.lua"]={["Path"]="scripts/actions/spells/white/diaga_iv.lua",["SHA256"]="68f62e40b5d9822751c0db115a071152e0c1e959b399dc6ee3ec749fd88935d8",["Text"]="-----------------------------------\n-- Spell: Diaga IV\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 7\n\n    -- Check for Bio\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = 4 + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = 180, origin = caster, tick = 3, subPower = 25, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/diaga_v.lua"]={["Path"]="scripts/actions/spells/white/diaga_v.lua",["SHA256"]="03cd4bc45dab2a352b8878702edc5bc834a8e50f6c0fc0c1bd67eccc9d5a2379",["Text"]="-----------------------------------\n-- Spell: Diaga V\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 9\n\n    -- Check for Bio\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = 5 + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = 180, origin = caster, tick = 3, subPower = 30, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/embrava.lua"]={["Path"]="scripts/actions/spells/white/embrava.lua",["SHA256"]="4df847f36e574a585ed3f1000910aea4b66e2ae789b35df259ca0e041becddec",["Text"]="-----------------------------------\n-- Spell: Embrava\n-- Consumes 20% of your maximum MP.\n-- Gradually restores target party member's HP and MP and increases attack speed.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enaero.lua"]={["Path"]="scripts/actions/spells/white/enaero.lua",["SHA256"]="3c8e5e4821c2dcab32f444e79a7b2e6a157db41d59b95c9fd554c78950321d73",["Text"]="-----------------------------------\n-- Spell: Enaero\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enaero_ii.lua"]={["Path"]="scripts/actions/spells/white/enaero_ii.lua",["SHA256"]="cdfc8ca10dfc392a1515da812e1400d5803ae990f5bb434f3961a0f14e32d4bf",["Text"]="-----------------------------------\n-- Spell: Enaero II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enblizzard.lua"]={["Path"]="scripts/actions/spells/white/enblizzard.lua",["SHA256"]="4b81461aa9788e173fb9e7f0839c6a396c0e4f6288d3baacc11f1e5a49968a3c",["Text"]="-----------------------------------\n-- Spell: Enblizzard\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enblizzard_ii.lua"]={["Path"]="scripts/actions/spells/white/enblizzard_ii.lua",["SHA256"]="2bee0bab13d83d7d12d98a4a92c20b37bda41b582ac261ca2541c58c906da7db",["Text"]="-----------------------------------\n-- Spell: Enblizzard II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enfire.lua"]={["Path"]="scripts/actions/spells/white/enfire.lua",["SHA256"]="09f61c96f9eb6a97f1949ad4a2ee1be2126e511ee394ee919060bafd9ead2be9",["Text"]="-----------------------------------\n-- Spell: Enfire\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enfire_ii.lua"]={["Path"]="scripts/actions/spells/white/enfire_ii.lua",["SHA256"]="b61bb28a6ba13515b0297f5f8a104e9e7440c5b6ebfdc00c29200ca4b9c8b0d0",["Text"]="-----------------------------------\n-- Spell: Enfire II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enlight.lua"]={["Path"]="scripts/actions/spells/white/enlight.lua",["SHA256"]="4a4e3bd467dac7aa9e0ff091c77d932866b6af408841368ac8598084ab50d195",["Text"]="-----------------------------------\n-- Spell: Enlight\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local effect = xi.effect.ENLIGHT\n    local magicskill = target:getSkillLevel(xi.skill.DIVINE_MAGIC)\n    local potency = (magicskill / 8) + 12.5\n\n    if target:addStatusEffect(effect, { power = potency, duration = 180, origin = caster }) then\n        spell:setMsg(xi.msg.basic.MAGIC_GAIN_EFFECT)\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return effect\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enstone.lua"]={["Path"]="scripts/actions/spells/white/enstone.lua",["SHA256"]="afb7f442e3696fa7b0d29e8eff52097d257ce0fdcdaf0f5f386533d82aabb355",["Text"]="-----------------------------------\n-- Spell: Enstone\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enstone_ii.lua"]={["Path"]="scripts/actions/spells/white/enstone_ii.lua",["SHA256"]="6423de6be6b83298c93dca47f240bcd8184388f9570b9c25c8f02b07d2b12c66",["Text"]="-----------------------------------\n-- Spell: Enstone II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enthunder.lua"]={["Path"]="scripts/actions/spells/white/enthunder.lua",["SHA256"]="da9deb8d52364709613f532d8e3cbd6cd39c736c2bf856e45a8fabba2136cdc2",["Text"]="-----------------------------------\n-- Spell: Enthunder\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enthunder_ii.lua"]={["Path"]="scripts/actions/spells/white/enthunder_ii.lua",["SHA256"]="0d59ca539acccf39da1286dced366e03f860d990168642c9847412b05cc20403",["Text"]="-----------------------------------\n-- Spell: Enthunder II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enwater.lua"]={["Path"]="scripts/actions/spells/white/enwater.lua",["SHA256"]="54ad6d965451616b04165c2ab802cc5edf587109393096db62d78d3a8e011a7c",["Text"]="-----------------------------------\n-- Spell: Enwater\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/enwater_ii.lua"]={["Path"]="scripts/actions/spells/white/enwater_ii.lua",["SHA256"]="09e2d627c5a8feca5823a222ecb8f2cfa11b1af298208fde87e7ec2bb8e25ebf",["Text"]="-----------------------------------\n-- Spell: Enwater II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/erase.lua"]={["Path"]="scripts/actions/spells/white/erase.lua",["SHA256"]="e37b698dc8387f8312c07602bb1443b9461944b84ee6e0e712b8db4abb986e25",["Text"]="-----------------------------------\n-- Spell: Erase\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local effect = target:eraseStatusEffect()\n\n    if effect == xi.effect.NONE then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT) -- no effect\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_ERASE)\n    end\n\n    return effect\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/esuna.lua"]={["Path"]="scripts/actions/spells/white/esuna.lua",["SHA256"]="4903a5fce2120ec9666915612cd58388171fc646fb5def57a6591c2ed62e4381",["Text"]="-----------------------------------\n-- Spell: Esuna\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    if caster:getID() == target:getID() then -- much of this should only run once per cast, otherwise it would only delete the debuffs from the caster.\n\n        local statusNum = -1\n        local removables =\n        {\n            xi.effect.FLASH,\n            xi.effect.BLINDNESS,\n            xi.effect.PARALYSIS,\n            xi.effect.POISON,\n            xi.effect.CURSE_I,\n            xi.effect.CURSE_II,\n            xi.effect.DISEASE,\n            xi.effect.PLAGUE,\n        }\n\n        -- add extra statuses to the list of removables. Elegy and Requiem are specifically absent.\n        if caster:hasStatusEffect(xi.effect.AFFLATUS_MISERY) then\n            removables =\n            {\n                xi.effect.FLASH,\n                xi.effect.BLINDNESS,\n                xi.effect.PARALYSIS,\n                xi.effect.POISON,\n                xi.effect.CURSE_I,\n                xi.effect.CURSE_II,\n                xi.effect.DISEASE,\n                xi.effect.PLAGUE,\n                xi.effect.WEIGHT,\n                xi.effect.BIND,\n                xi.effect.BIO,\n                xi.effect.DIA,\n                xi.effect.BURN,\n                xi.effect.FROST,\n                xi.effect.CHOKE,\n                xi.effect.RASP,\n                xi.effect.SHOCK,\n                xi.effect.DROWN,\n                xi.effect.STR_DOWN,\n                xi.effect.DEX_DOWN,\n                xi.effect.VIT_DOWN,\n                xi.effect.AGI_DOWN,\n                xi.effect.INT_DOWN,\n                xi.effect.MND_DOWN,\n                xi.effect.CHR_DOWN,\n                xi.effect.ADDLE,\n                xi.effect.SLOW,\n                xi.effect.HELIX,\n                xi.effect.ACCURACY_DOWN,\n                xi.effect.ATTACK_DOWN,\n                xi.effect.EVASION_DOWN,\n                xi.effect.DEFENSE_DOWN,\n                xi.effect.MAGIC_ACC_DOWN,\n                xi.effect.MAGIC_ATK_DOWN,\n                xi.effect.MAGIC_EVASION_DOWN,\n                xi.effect.MAGIC_DEF_DOWN,\n                xi.effect.MAX_TP_DOWN,\n                xi.effect.MAX_MP_DOWN,\n                xi.effect.MAX_HP_DOWN,\n            }\n        end\n\n        local has = {}\n\n        -- collect a list of what caster currently has\n        for i, effect in ipairs(removables) do\n            if caster:hasStatusEffect(effect) then\n                statusNum = statusNum + 1\n                has[statusNum] = removables[i]\n            end\n        end\n\n        local delEff = 0\n        if statusNum >= 0 then -- make sure this happens once instead of for every target\n            delEff = math.randomInt(0, statusNum) -- pick a random status to delete\n            caster:setLocalVar('esunaDelEff', has[delEff]) -- this can't be a local because it would only delete from the caster if it were.\n        else -- clear it if the caster has no eligible statuses, otherwise it will remove the status from others if it was previously removed.\n            caster:setLocalVar('esunaDelEff', 0)\n            caster:setLocalVar('esunaDelEffMis', 0)  -- again, this can't be a local because it would only delete from the caster if it were. For extra status deletion under Misery\n        end\n\n        if statusNum >= 1 and caster:hasStatusEffect(xi.effect.AFFLATUS_MISERY) then -- Misery second status removal.\n            caster:delStatusEffect(has[delEff]) -- delete the first selected effect so it doesn't get selected again. Won't impact the ability to delete it from others at this point.\n            local statusNumMis =  - 1 -- need a new var to track the amount of debuffs for the array\n\n            -- collect a list of what caster currently has, again.\n            has = {}\n            for i, effect in ipairs(removables) do\n                if caster:hasStatusEffect(effect) then\n                    statusNumMis = statusNumMis + 1\n                    has[statusNumMis] = removables[i]\n                end\n            end\n\n            local delEffMis = math.randomInt(0, statusNumMis) -- pick another random status to delete\n            caster:setLocalVar('esunaDelEffMis', has[delEffMis])\n        else\n            caster:setLocalVar('esunaDelEffMis', 0)\n        end\n    end\n\n    local statusDel = caster:getLocalVar('esunaDelEff')\n    local statusDelMis = caster:getLocalVar('esunaDelEffMis')\n\n    if statusDel == 0 then -- this gets set to 0 if there's no status to delete.\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT) -- no effect\n    elseif statusDelMis ~= 0 then -- no need to check for statusDelMis because it can't be 0 if this isn't\n        target:delStatusEffect(statusDel)\n        target:delStatusEffect(statusDelMis)\n    else\n        target:delStatusEffect(statusDel)\n    end\n\n    return statusDel\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/firestorm.lua"]={["Path"]="scripts/actions/spells/white/firestorm.lua",["SHA256"]="f693766d0f22af3530ae8f9420e53b356a7f878b07cded942b3989f14bb9319b",["Text"]="-----------------------------------\n-- Spell: Firestorm\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/flash.lua"]={["Path"]="scripts/actions/spells/white/flash.lua",["SHA256"]="80ed7c4ff077e29283649659106f6504ba367fa543ddd2a0844b4f563eab5771",["Text"]="-----------------------------------\n-- Spell: Flash\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/flurry.lua"]={["Path"]="scripts/actions/spells/white/flurry.lua",["SHA256"]="0efdee11ab98b178c6619f56dcacbab4f2f992bc63476d95f0fa863b1e8d3fcc",["Text"]="-----------------------------------\n-- Spell: Flurry\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/flurry_ii.lua"]={["Path"]="scripts/actions/spells/white/flurry_ii.lua",["SHA256"]="d5882c65d23ffcc591dfe98eb7851ac0834bfb1d2f5f293a8111aa2865aa43eb",["Text"]="-----------------------------------\n-- Spell: Flur